"""Original passages: observed oral reading, plus specific monitoring decisions."""
import json
from pathlib import Path
items=[]
def base(b,q):
 n=sum(x['bank']==b for x in items)+1
 return dict(id=f'AC9E3LY04-{b[0].upper()}-{n:03d}',subject='english',year_level='Year 3',curriculum_code='AC9E3LY04',bank=b,skill='Read accurately and fluently',question=q,audio_prompt=q,visual={'type':'none'})
def mc(b,t,ask,c,w,why):
 x=base(b,t+'\n\n'+ask);p=sum(a['bank']==b and a.get('grading_mode')!='adult-review' for a in items)%4;o=w[:];o.insert(p,c);x.update(answers=[{'text':s,'is_correct':j==p} for j,s in enumerate(o)],correct_index=p,explanation={'summary':why,'hint':'Check the printed letters, then reread the sentence for grammar and meaning.'});items.append(x)
def oral(b,t,focus,check,model):
 x=base(b,t+'\n\nRead this whole passage aloud to an adult. '+focus+' '+check)
 x.update(grading_mode='adult-review',answers=[],correct_index=None,model_answer=model,acceptance_note='An adult must hear the passage, not just read the typed response. '+model+' Check accurate words, connected phrasing and attention to meaning. Allow a comfortable pace and the learner’s accent. Accept accurate first reading; a deliberate error is not required. If help or a model reading is needed, practise and then try the passage independently before marking it as achieved.',response_instructions='Read aloud while an adult listens. If a word does not sound right, look through its letters, blend it and reread the sentence. Answer the short meaning check aloud; you may record the adult’s observations here.',completion_label='I have read aloud; an adult still needs to check my reading.',explanation={'summary':model,'hint':'Look through the whole word. Use the sentence to check your reading, rather than guessing from its topic.'});items.append(x)
mc('practice','Printed: The frog sprang from the rock. / Reader says: The frog sang from the rock.','Which part needs checking?','The p and r in sprang, followed by rereading the sentence.',['Change frog to bird because birds sing.','Ignore the extra printed letters because sang is a real word.','Change rock to tree to fit the spoken version.'],'Sprang contains p and r after s. The reader must match the print rather than rewrite its meaning.')
mc('practice','Printed: The string slipped through my fingers.','Which beginning belongs to string?','str',['spr','scr','spl'],'String begins s-t-r; keep all three consonant sounds when blending.')
mc('practice','Printed: The seeds sprouted after rain. / Reader says: The seeds sported after rain.','What should the reader do?','Look through sprouted, blend its parts and reread to check the growing meaning.',['Keep sported because it begins with s.','Skip the word whenever a sentence mentions seeds.','Replace after with before.'],'The order of letters and the ou spelling need checking; sprouted fits both the print and seeds beginning to grow.')
mc('practice','Printed: Yesterday the ducks landed beside the pond. / Reader says: Yesterday the ducks land beside the pond.','What was missed?','The ed ending showing the completed action.',['The plural ending on ducks.','The first letter of pond.','The word beside was printed twice.'],'Landed is the printed form; yesterday also supports a past action.')
mc('practice','Printed: The small boxes were stacked neatly. / Reader says: The small box were stacked neatly.','Which correction matches the print and grammar?','Read boxes, keeping its plural ending.',['Change were to was without checking boxes.','Read boxed because it ends with d.','Leave out small and keep box.'],'The noun is boxes and the verb were agrees with the plural noun.')
mc('practice','Printed: “Wait, Max!” called Iris.','Which reading keeps the meaning clear?','A small pause after Wait, then Max as the person being called.',['Read Wait Max as one new word.','Ignore the comma and never pause at the end.','Pause between every letter in Iris.'],'The comma separates the instruction from the person addressed.')
mc('practice','Printed: We sat on the river bank and watched the water.','Which meaning helps check bank here?','The ground beside a river.',['A place that keeps money.','A row of computer switches.','A turning aircraft.'],'River and watched the water establish this meaning; the reader still needs to read the letters in bank accurately.')
mc('practice','Printed: Please close the gate behind you. / Reader says: Please chose the gate behind you.','Which check is useful?','Notice the l in close and reread the request.',['Keep chose because both words end in ose.','Change gate to gift.','Read only the first and last letters.'],'Close contains l and makes sense as the requested action; chose has a different spelling and meaning.')
mc('practice','Printed: After the rain stopped, the players returned to the oval.','Where is a useful brief pause?','After stopped, at the comma.',['Between the and rain.','Inside the word returned.','After every single word for the same long time.'],'The comma ends the opening time group; grouping these words supports fluent meaning.')
mc('practice','Printed: “Is our bus here?” asked Mei.','Which feature should guide the voice?','The question mark: Mei is asking, not stating an arrival.',['The capital I means the whole line must be shouted.','The quotation marks mean omit the spoken words.','The full stop after Mei makes the quoted question a command.'],'The spoken words ask a question; reading should preserve that purpose without requiring one exact intonation.')
mc('practice','Printed: The light bag was easy to carry.','Which meaning of light fits?','Not heavy.',['A lamp.','A pale colour, with no weight meaning.','To start a fire.'],'Easy to carry gives the weight meaning in this sentence.')
mc('practice','Printed: Finn did not open the parcel. / Reader says: Finn did open the parcel.','Why should the reader go back?','Missing not reverses what Finn did.',['Did and not mean exactly the same thing.','The parcel’s colour is missing.','Every sentence about Finn must be read faster.'],'Not is printed and changes the action from opening to not opening.')
p='''A splash came from the shallow pool. A frog sprang onto a flat stone. Its wet feet left small marks before it slipped into the reeds.|Keep the spl and spr beginnings clear.|Where did the frog go at the end?|Listen for splash, sprang and slipped without lost consonants; the frog ends in the reeds.
Rae stretched a string between two sticks. She clipped three paper flags to it. A strong breeze lifted the flags, but the knots held.|Read the str beginnings without adding a vowel between the consonants.|What kept the flags attached?|Check stretched, string and strong; knots held the string and attached flags in place.
The gardener scraped mud from a spade. Under the mud was a scratch in the metal. He cleaned the blade and put the spade away.|Look carefully through scraped and scratch.|What did the mud hide?|Check scr and the ending of scraped; the mud hid a scratch.
A stripe ran down the toy’s back. When Jo pressed its tail, a spring lifted its head. Jo laughed and tried the button again.|Distinguish stripe from spring.|What made the head rise?|Listen for str versus spr and smooth sentence groups; the spring lifted the head when the tail was pressed.
Seeds need suitable warmth and water to begin growing. A tiny root appears first. A shoot then grows towards the light, and leaves begin to open.|Group the sentences so the stages are clear.|Which part appears before the shoot?|Hear seeds, suitable and towards accurately; the root appears first.
Wrap the dry seed in damp paper. Place it in a clear jar. Check the paper each day and add a little water if it becomes dry.|Give each instruction its own clear phrase.|When should more water be added?|Check wrap, damp and becomes; add water if the paper becomes dry, not continuously.
At dusk, the path grew dim. Nia switched on her torch. A moth fluttered through the beam and disappeared beyond the gate.|Keep the ed ending in switched and the parts of disappeared.|What helped Nia see the path?|Listen for switched, fluttered and disappeared; the torch lit the dim path.
The puppies tumbled out of their basket. One puppy stayed asleep beneath a blanket. The others padded towards the kitchen.|Make puppy and puppies sound different.|How many stayed asleep?|Keep plural puppies and others distinct from one puppy; one remained asleep.
Yesterday we carried chairs into the hall. Today we are painting signs. Tomorrow we will welcome families to our display.|Let the time words guide your phrasing.|Which job has already happened?|Check carried, painting and will welcome without changing tense; carrying chairs happened yesterday.
“Is this seat free?” asked Omar. “Yes,” said Liv. She moved her bag so he could sit beside her.|Use the punctuation to separate the two speakers.|Why did Liv move her bag?|Hear the question and reply as separate speech; she made space for Omar to sit.
“Stop!” called the coach. The ball had rolled towards the road. Everyone waited inside the fence while an adult fetched it.|Show the urgent command without needing to shout.|Who collected the ball?|Keep had rolled and while an adult fetched it accurate; the adult fetched the ball.
After lunch, we visited the pond. Before we left, we counted six ducks. On the way home, rain began to fall.|Pause naturally after the opening time groups.|Did rain begin before or after the pond visit?|Retain after lunch, before we left and on the way home; rain began after the visit.
The bat flew over the shed. It turned above a flowering tree, then vanished into the dark. We heard no cricket ball or cheering crowd.|Read bat using the meaning supported by the whole passage.|Is this bat an animal or sports equipment?|The flight and turning identify an animal; keep flowering and vanished accurate rather than replacing unfamiliar words.
Mum put a stamp on the envelope. She did not stamp on it with her foot. Then she carried the letter to the postbox.|Notice how the same printed word is used in two ways.|What went on the envelope?|The first stamp is the postage item; the second names an action. Preserve not and read both sentences accurately.
A cool wind blew across the lake. We pulled our coats close and watched the boats return. Nobody wanted to stay on the cold shore.|Keep blew distinct from blow and close distinct from chose.|Why did people pull their coats close?|The wind and cold shore support keeping warm; hear blew and close and connected noun groups.
The class was quiet. No one spoke while Sam read the last page. When the story ended, hands shot up with questions.|Do not miss the short words no and last.|When did the questions begin?|Preserve no one and when; questions began after the story ended.
A line of ants crossed the path beside the gate. Each ant carried a crumb. We stepped around the line so we would not crush them.|Keep beside the gate together as a place group.|Why did the walkers step around the line?|Accurate crossed, carried and would not; the walkers avoided crushing ants.
The little boat, with its bright red sail, drifted past the jetty. Its owner followed along the bank until it reached a patch of reeds.|Use the commas to group the extra detail about the sail.|Where did the boat finish this journey?|Do not lose the main link boat drifted; the boat reaches reeds.
Tap, tap, rain on the tin. / Drip, drip, water comes in. / Set down a bowl and listen awhile: / plip goes a drop, and we share a smile.|Read the poem’s sound groups smoothly; do not rush to make it rhyme.|Why is a bowl put down?|Hear tin/in and awhile/smile while preserving words; the bowl catches incoming drops.
Softly the evening settles here. / One little cricket sings quite near. / The busy day has slipped away. / I close my book and end my day.|Let the line endings and sentences guide comfortable pauses.|What does the speaker close?|Accurate settles, cricket and slipped, with calm connected phrasing; the speaker closes a book.
The museum opens at ten. Families may leave bags in the lockers near the door. Please keep the walkway clear for other visitors.|Read as useful information and a polite instruction.|Where can bags be left?|Hear opens, lockers and walkway; bags go in lockers near the door.
Lost: one blue scarf with yellow stripes. Last seen on the bench by the oval. Please take it to the school office if you find it.|Treat each notice line as a complete information group.|Where should a finder take the scarf?|Keep stripes and last seen accurate; take it to the school office.
Dear Gran, our beans have grown above the fence. Dad tied them to tall poles. I will show you the flowers when you visit. Love, Cleo.|Read the greeting and ending separately from the message.|What will Cleo show Gran?|Check grown, tied and flowers; Cleo will show the flowers, not claim beans have already been picked.
We made two paper bridges. The wide bridge held three counters. The narrow bridge sagged when we added the second counter. We wrote down both results.|Preserve the comparison and number words.|Which bridge held three counters?|Hear wide versus narrow and three versus second; the wide bridge held three.
The chef stirred the thick soup. Steam rose from the pot, so we stood back while she lifted the lid. She let the soup cool before serving.|Check all the sounds in stirred and the ending of lifted.|Why did everyone stand back?|Steam rose from the pot; check before so the cooling happens before serving.
A small shell lay beside a larger shell. Both were empty. We looked closely at their patterns, then left them where we had found them.|Keep small, larger and both clear.|Did the walkers take the shells away?|Accurate larger, patterns and had found; they left both shells in place.
“You can lead our group,” said Tess. Ben picked up the map. “I will follow the blue path,” he replied. The others gathered behind him.|Use lead as the action of guiding; check the sentence if it sounds wrong.|What colour path will Ben follow?|Lead here has the vowel sound in seed; blue is the chosen path. Accept accent variation, not a different word.
The wind made the wind chime ring. Its metal tubes touched gently. Later the air grew still and the soft ringing stopped.|Read both uses of wind with the same meaning here.|Why did the ringing stop?|Both wind occurrences refer to moving air; when the air grew still the tubes stopped ringing.
Kai packed a snack, a hat and a bottle of water. He checked the list before closing his bag. His coat was already hanging by the door.|Use the commas to make the list clear.|Where was the coat?|Hear three listed objects without merging them; the coat hangs by the door, not inside the bag.
The runner slowed at the corner because the path was slippery. Once past the wet patch, she returned to a steady pace. She reached the finish smiling.|Keep because joined to the reason it introduces.|What made the runner slow down?|Check slippery and steady; the slippery path caused the slowdown, with pace increasing again afterwards.
Please do not feed the ducks bread. This pond has a feeding station with suitable food. Ask the keeper before taking any from the container.|Keep not in the first instruction.|Who should visitors ask?|Preserve do not and before; ask the keeper before taking suitable food.
When the bell rang, the class stayed seated. Their visitor was still speaking. They waited until she finished, then walked outside together.|Let until show when the action changes.|Did the class leave as soon as the bell rang?|Accurate stayed, speaking and finished; they waited for the visitor to finish.
Under the stairs stood a wooden chest. Mina opened it slowly. Inside were costumes, a painted crown and a note inviting her to make a play.|Read the long final sentence in meaningful groups.|What was Mina invited to make?|Hear wooden, costumes and inviting accurately; she was invited to make a play.
A tiny crack appeared in the egg. The chick pushed again, and the shell opened wider. At last its damp head appeared beneath the warm feathers.|Use punctuation to keep the hatching sequence clear.|What appeared at the end?|Check crack, pushed and wider; the chick’s damp head appeared.
The map showed a bridge north of the lake. We crossed that bridge, then turned towards the picnic area. A sign told us we had arrived.|Keep the directions in their printed order.|What did the walkers cross before turning?|Hear north of the lake and crossed that bridge; they crossed the bridge before turning.
I thought the cupboard was empty, but a faint rustle came from inside. I opened the door and found our paper decorations sliding off a shelf. No animal was hiding there.|Read the turn after but and retain no.|What actually made the rustle?|Check thought, rustle and decorations; falling paper decorations explain the sound, not an animal.'''
for l in p.splitlines():oral('practice',*l.split('|'))
mc('test','Printed: A strong wind swept the leaves away. / Reader says: A song wind swept the leaves away.','Which correction matches the print?','Keep t and r in strong and reread the sentence.',['Replace wind with singer.','Remove swept because song is a real word.','Leave strong out altogether.'],'Strong has the str blend; song omits printed consonants and does not fit this noun group.')
mc('test','Printed: The children were waiting beside two buses. / Reader says: The children were waiting beside two bus.','What needs correction?','Read the plural ending in buses.',['Change two to one.','Change children to child but leave were.','Remove waiting.'],'Buses is printed and agrees in meaning with two; the reader should not edit the text to fit a misreading.')
mc('test','Printed: Before you lift the lid, switch off the machine.','Which phrasing preserves the instruction?','Group Before you lift the lid, then switch off the machine.',['Pause halfway through machine.','Join lid switch as if it were one noun and ignore the comma.','Treat Before as if it said After.'],'The opening group and comma make clear that switching off must happen before lifting.')
mc('test','Printed: The branch bent but did not break. / Reader says: The branch bent and did break.','Why reread?','Both but and not have been changed or missed, reversing the outcome.',['The printed sentence says the branch broke.','Bent always means broken.','Only the branch’s colour matters.'],'The printed branch remains unbroken; accurate reading must retain the contrast and negation.')
t='''A spring breeze shook the blossom. Three petals landed on the path. Priya stretched out a hand, but the next petal slipped past her fingers.|Keep spring, stretched and slipped distinct.|Did Priya catch the next petal?|Listen for complete consonant groups and the contrast after but; the next petal slipped past.
The scribbled note was hard to read. Eli looked at each line again and slowly worked out the words. It said the spare key was in the drawer.|Read each sentence without dropping small words.|Where was the spare key?|Check scribbled, slowly and spare; the key was in the drawer.
Last week the class planted bulbs. This morning a green tip appeared in one pot. The children will check the other pots again tomorrow.|Preserve the changes of time.|When will the other pots be checked again?|Hear planted, appeared and will check in their printed forms; tomorrow is the next check.
“May I borrow the ruler?” asked Zac. “When I finish this line,” said Ana. Zac waited beside the table instead of taking it straight away.|Separate the request and reply through phrasing.|Why did Zac wait?|Ana needed to finish her line; observe accurate speech and narrative, not just a correct meaning answer.
Beyond the gate, a narrow path curved towards the beach. We followed it until the sand began. Then we removed our shoes and sat near the dunes.|Group the opening place words and follow the punctuation.|When were the shoes removed?|Accurate beyond, curved and until; shoes were removed after reaching sand.
The coach left the coach near the oval and walked to the players. The large vehicle would take the team home after the match.|Use the surrounding sentences to distinguish the two meanings of coach.|Which coach is the vehicle?|The second coach is the vehicle; the first is the person walking to players. Hear all words accurately as well as the explanation.
A bowl stood under the dripping tap. It was nearly full, so Dad turned the tap off and emptied the bowl. The sink was dry again before dinner.|Keep nearly and before; they help the sequence make sense.|Why did Dad turn off the tap?|The dripping tap was filling the bowl; listen for connected cause and action with no omitted words.
First fold the card in half. Next draw a window on the front. Finally write a short message inside. Leave the card open while the ink dries.|Make each step easy for a listener to follow.|Why leave the card open?|Preserve first, next, finally and while; it stays open while the ink dries.
Clink goes the spoon in the cup. / Steam curls gently up and up. / We wait a while before we sip. / Then warm tea touches each small lip.|Keep the words clear while following the poem’s sound pattern.|Do the speakers sip immediately?|Listen for clink, gently and before; they wait before sipping.
Please leave wet umbrellas in the stand by the entrance. Dry bags may be carried inside. This helps keep the reading room floor free of puddles.|Read the instruction and explanation as connected ideas.|What should stay by the entrance?|Accurate umbrellas, entrance and puddles; wet umbrellas stay in the stand.
The kite did not fall when the breeze faded. Its tail caught on a twig. We lowered the branch carefully and freed the string before packing up.|Retain not and read the final actions in order.|What held the kite up?|The tail caught on a twig; hear did not fall and freed accurately, with order retained.
Our first cardboard tower leaned to one side. We widened its base and tried again. This time it stood without support while we placed a flag on top.|Let this time mark the changed result.|What change helped the tower stand?|The base was widened; observe accurate first reading or a successful self-correction and connected phrasing.'''
for l in t.splitlines():oral('test',*l.split('|'))
assert len(items)==64,len(items)
assert sum(x['bank']=='practice' for x in items)==48
Path(__file__).with_name('ac9e3ly04.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
